alter table public.profiles enable row level security;alter table public.quizzes enable row level security;alter table public.questions enable row level security;alter table public.answers enable row level security;alter table public.quiz_sessions enable row level security;alter table public.submissions enable row level security;alter table public.student_answers enable row level security;
create policy "profile owner reads own profile" on public.profiles for select to authenticated using(id=auth.uid());create policy "profile owner updates own profile" on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy "teachers manage own quizzes" on public.quizzes for all to authenticated using(teacher_id=auth.uid()) with check(teacher_id=auth.uid());
create policy "teachers manage own questions" on public.questions for all to authenticated using(exists(select 1 from public.quizzes q where q.id=quiz_id and q.teacher_id=auth.uid())) with check(exists(select 1 from public.quizzes q where q.id=quiz_id and q.teacher_id=auth.uid()));
create policy "teachers manage answer keys" on public.answers for all to authenticated using(exists(select 1 from public.questions x join public.quizzes q on q.id=x.quiz_id where x.id=question_id and q.teacher_id=auth.uid())) with check(exists(select 1 from public.questions x join public.quizzes q on q.id=x.quiz_id where x.id=question_id and q.teacher_id=auth.uid()));
create policy "students and teachers see sessions" on public.quiz_sessions for select to authenticated using(participant_id=auth.uid() or exists(select 1 from public.quizzes q where q.id=quiz_id and q.teacher_id=auth.uid()));
create policy "students join published quizzes" on public.quiz_sessions for insert to authenticated with check(participant_id=auth.uid() and exists(select 1 from public.quizzes q where q.id=quiz_id and q.status='published'));
create policy "participants update own active session" on public.quiz_sessions for update to authenticated using(participant_id=auth.uid() and status='in_progress') with check(participant_id=auth.uid());
create policy "teachers see quiz submissions" on public.submissions for select to authenticated using(exists(select 1 from public.quizzes q where q.id=quiz_id and q.teacher_id=auth.uid()));
create policy "participants create own submission" on public.submissions for insert to authenticated with check(exists(select 1 from public.quiz_sessions s where s.id=session_id and s.quiz_id=quiz_id and s.participant_id=auth.uid() and s.status='in_progress'));
create policy "teachers grade own quiz answers" on public.student_answers for all to authenticated using(exists(select 1 from public.submissions s join public.quizzes q on q.id=s.quiz_id where s.id=submission_id and q.teacher_id=auth.uid())) with check(exists(select 1 from public.submissions s join public.quizzes q on q.id=s.quiz_id where s.id=submission_id and q.teacher_id=auth.uid()));
create policy "participants see own answers" on public.student_answers for select to authenticated using(exists(select 1 from public.submissions s join public.quiz_sessions x on x.id=s.session_id where s.id=submission_id and x.participant_id=auth.uid()));
create policy "participants write own answers" on public.student_answers for insert to authenticated with check(exists(select 1 from public.submissions s join public.quiz_sessions x on x.id=s.session_id where s.id=submission_id and x.participant_id=auth.uid()));
create policy "participants see own submissions" on public.submissions for select to authenticated using(exists(select 1 from public.quiz_sessions x where x.id=session_id and x.participant_id=auth.uid()));
grant select,insert,update,delete on public.quizzes,public.questions,public.answers to authenticated;grant select,insert,update on public.quiz_sessions to authenticated;grant select,insert on public.submissions,public.student_answers to authenticated;grant select,update on public.student_answers to authenticated;grant select,update on public.profiles to authenticated;
create or replace function public.publish_quiz(quiz_id uuid) returns text language plpgsql security definer set search_path=public as $$ declare code text; begin if not exists(select 1 from public.quizzes where id=quiz_id and teacher_id=auth.uid()) then raise exception 'not found'; end if; if not exists(select 1 from public.questions where questions.quiz_id=publish_quiz.quiz_id) then raise exception 'quiz needs questions'; end if; update public.quizzes set access_code=coalesce(access_code, lpad((floor(random()*1000000)::int)::text,6,'0')),status='published',published_at=coalesce(published_at,now()),closed_at=null where id=quiz_id returning access_code into code; return code; end $$;
create or replace function public.get_public_quiz(quiz_code text) returns jsonb language sql security definer set search_path=public as $$ select jsonb_build_object('id',q.id,'title',q.title,'description',q.description,'subject',q.subject) from public.quizzes q where q.access_code=quiz_code and q.status='published' $$;
create or replace function public.join_quiz(quiz_code text,display_name text) returns uuid language plpgsql security definer set search_path=public as $$ declare quiz_uuid uuid; session_uuid uuid; begin select id into quiz_uuid from public.quizzes where access_code=quiz_code and status='published'; if quiz_uuid is null then raise exception 'quiz unavailable'; end if; insert into public.quiz_sessions(quiz_id,participant_id,student_name) values(quiz_uuid,auth.uid(),trim(display_name)) on conflict(quiz_id,participant_id) do update set student_name=excluded.student_name,status='in_progress',submitted_at=null returning id into session_uuid; return session_uuid; end $$;
create or replace function public.session_quiz(session_id uuid) returns jsonb language plpgsql security definer set search_path=public,storage as $$ declare result jsonb; begin if not exists(select 1 from public.quiz_sessions where id=session_id and participant_id=auth.uid() and status='in_progress') then raise exception 'session unavailable'; end if; select jsonb_build_object('title',q.title,'student_name',s.student_name,'questions',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'question_text',x.question_text,'question_type',x.question_type,'points',x.points,'audio_url',case when x.teacher_audio_path is null then null else (storage.create_signed_url('teacher-audio',x.teacher_audio_path,3600)).signedURL end,'answers',(select jsonb_agg(jsonb_build_object('id',a.id,'answer_text',a.answer_text) order by a.position) from public.answers a where a.question_id=x.id)) order by x.position) from public.questions x where x.quiz_id=q.id),'[]'::jsonb)) into result from public.quiz_sessions s join public.quizzes q on q.id=s.quiz_id where s.id=session_id; return result; end $$;
create or replace function public.submit_quiz(session_id uuid,answer_payload jsonb) returns uuid language plpgsql security definer set search_path=public as $$ declare s public.quiz_sessions; sub_id uuid; q record; a jsonb; score numeric:=0; maximum numeric:=0; awarded numeric; is_right boolean; expected uuid[]; selected uuid[]; begin select * into s from public.quiz_sessions where id=session_id and participant_id=auth.uid() and status='in_progress' for update; if not found then raise exception 'session unavailable'; end if; insert into public.submissions(quiz_id,session_id,maximum_score) values(s.quiz_id,s.id,(select coalesce(sum(points),0) from public.questions where quiz_id=s.quiz_id)) returning id into sub_id; for q in select * from public.questions where quiz_id=s.quiz_id loop a:=coalesce((select v from jsonb_array_elements(answer_payload) v where v->>'question_id'=q.id::text limit 1),'{}'::jsonb); awarded:=null; if q.question_type in('multiple_choice','true_false') then select array_agg(id order by id) into expected from public.answers where question_id=q.id and is_correct; select array_agg((v#>>'{}')::uuid order by (v#>>'{}')::uuid) into selected from jsonb_array_elements_text(coalesce(a->'selected_answer_ids','[]'::jsonb)) v; is_right:=coalesce(expected,'{}')=coalesce(selected,'{}'); awarded:=case when is_right then q.points else 0 end; score:=score+awarded; end if; insert into public.student_answers(submission_id,question_id,answer_text,selected_answer_ids,awarded_points,review_status) values(sub_id,q.id,a->>'answer_text',coalesce(array(select (v#>>'{}')::uuid from jsonb_array_elements(coalesce(a->'selected_answer_ids','[]'::jsonb)) v),'{}'),awarded,case when awarded is null then 'pending'::public.review_kind else 'auto'::public.review_kind end); end loop; update public.submissions set total_score=score,grading_status=case when exists(select 1 from public.student_answers where submission_id=sub_id and review_status='pending') then 'partial' else 'complete' end where id=sub_id; update public.quiz_sessions set status='submitted',submitted_at=now() where id=s.id; return sub_id; end $$;
grant execute on function public.publish_quiz(uuid),public.get_public_quiz(text),public.join_quiz(text,text),public.session_quiz(uuid),public.submit_quiz(uuid,jsonb) to authenticated;
